[package]
name = "app"
version = "0.1.0"
edition = "2021"
publish = false

[features]
opt = ["dep:optdep", "dep:optdep_unused"]

[dependencies]
pathused = { path = "../libs/pathused" }
unused_dep = { path = "../libs/unused_dep" }
devonly = { path = "../libs/devonly" }
macrodep = { path = "../libs/macrodep" }
renamed = { package = "pathused2", path = "../libs/pathused2" }
alias_unused = { package = "renamed_unused_pkg", path = "../libs/renamed_unused_pkg" }
optdep = { path = "../libs/optdep", optional = true }
optdep_unused = { path = "../libs/optdep_unused", optional = true }

[target.'cfg(unix)'.dependencies]
tdep = { path = "../libs/tdep" }
tdep_unused = { path = "../libs/tdep_unused" }

[build-dependencies]
builddep = { path = "../libs/builddep" }
builddep_unused = { path = "../libs/builddep_unused" }

[dev-dependencies]
devunused = { path = "../libs/devunused" }

